#' Campionamento a grappoli
#'
#' 
#' @param data .
#' @param cluster_var Variabile che identifica i grappoli (es. città, scuola,
#'   quartiere). Le unità all'interno di uno stesso grappolo dovrebbero essere
#'   tra loro eterogenee rispetto al fenomeno di interesse: il metodo è
#'   efficiente quando i grappoli sono "piccole popolazioni" simili tra loro.
#' @param id_var Variabile usata per identificare le singole unità nel
#'   dataset. Se specificata, la tabella "Unità estratte" mostra gli ID dei
#'   soggetti selezionati.
#' @param tuto .
#' @param size_mode Indica se si specifica un numero assoluto di grappoli da
#'   estrarre o una frazione dei grappoli totali.
#' @param ng Numero di grappoli (cluster) da estrarre dalla popolazione.
#' @param fg Frazione f_g = n_g / M dei grappoli da estrarre.
#' @param seed .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$clusters} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$extracted} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$out_freq} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
samplecluster <- function(
    data,
    cluster_var,
    id_var,
    tuto = TRUE,
    size_mode = "ng",
    ng = 3,
    fg = 0.3,
    seed = 1) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("samplecluster requires jmvcore to be installed (restart may be required)")

    if ( ! missing(cluster_var)) cluster_var <- jmvcore::resolveQuo(jmvcore::enquo(cluster_var))
    if ( ! missing(id_var)) id_var <- jmvcore::resolveQuo(jmvcore::enquo(id_var))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(cluster_var), cluster_var, NULL),
            `if`( ! missing(id_var), id_var, NULL))


    options <- sampleclusterOptions$new(
        cluster_var = cluster_var,
        id_var = id_var,
        tuto = tuto,
        size_mode = size_mode,
        ng = ng,
        fg = fg,
        seed = seed)

    analysis <- sampleclusterClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

